#!/usr/bin/env bash
# Removes the trailing "---" + "_Generated by [Claude Code](...)_" footer from 14 reviews.
# Run locally with `gh` logged in as Emmanuellsensai. Requires python3.
# Usage: bash remove_review_footers.sh
set -u
REPO=sorolens/sorolens
LOGIN=$(gh api user --jq .login)
[ "$LOGIN" = "Emmanuellsensai" ] || { echo "Logged in as '$LOGIN', expected Emmanuellsensai. Stop."; exit 1; }

REVIEWS="923:6002979979 921:6002983702 914:6002982967 908:6002948286 907:6002952908 905:6002977383 900:6002970318 894:6002969980 893:6002972491 892:6002978199 890:6002970309 883:6002970827 881:6002972547 877:6002951068"
WORK=$(mktemp -d)
printf '%-5s %-8s %s\n' PR RESULT DETAIL

for p in $REVIEWS; do
  PR=${p%%:*}; ID=${p##*:}
  URL="repos/$REPO/pulls/$PR/reviews/$ID"
  gh api "$URL" > "$WORK/$PR.before.json" 2>"$WORK/$PR.err" || { printf '%-5s %-8s %s\n' "$PR" FAILED "GET: $(cat "$WORK/$PR.err")"; continue; }

  python3 - "$WORK/$PR.before.json" "$WORK/$PR.req" <<'EOF'
import json, re, sys
d = json.load(open(sys.argv[1]))
if d["user"]["login"] != "Emmanuellsensai" or d["state"] != "CHANGES_REQUESTED":
    sys.exit(2)
b = d["body"]
m = re.search(r'\n*---\s*\n_Generated by \[Claude Code\]\(https://claude\.ai/code\)_\s*$', b)
if not m:
    sys.exit(3)
json.dump({"body": b[:m.start()]}, open(sys.argv[2], "w"))
EOF
  rc=$?
  case $rc in
    2) printf '%-5s %-8s %s\n' "$PR" SKIPPED "author/state mismatch"; continue;;
    3) printf '%-5s %-8s %s\n' "$PR" SKIPPED "footer not found (already clean or different wording)"; continue;;
  esac

  gh api -X PUT "$URL" --input "$WORK/$PR.req" >/dev/null 2>"$WORK/$PR.err" || { printf '%-5s %-8s %s\n' "$PR" FAILED "PUT: $(cat "$WORK/$PR.err")"; continue; }
  gh api "$URL" > "$WORK/$PR.after.json"

  python3 - "$WORK/$PR.before.json" "$WORK/$PR.after.json" "$PR" <<'EOF'
import json, sys
o = json.load(open(sys.argv[1])); a = json.load(open(sys.argv[2]))
bad = [w for w in ("Generated by", "Claude Code", "claude.ai") if w in a["body"]]
state_ok = a["state"] == o["state"]
print("%-5s %-8s %s" % (sys.argv[3], "done" if not bad and state_ok else "CHECK",
      "len %d -> %d, state %s%s" % (len(o["body"]), len(a["body"]), a["state"], ", footer still present" if bad else "")))
EOF
done
echo "Work files (before/after JSON): $WORK"
